import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.C4u7U0Dw.js";const h=JSON.parse('{"title":"第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill.md","filePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill.md"}'),e={name:"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill.md"};function o(n,l,p,r,d,u){return t(),i("div",null,[...l[0]||(l[0]=[s(`<h1 id="第-17-章-打造-skill-将方法论蒸馏为可执行-skill" tabindex="-1">第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill <a class="header-anchor" href="#第-17-章-打造-skill-将方法论蒸馏为可执行-skill" aria-label="Permalink to &quot;第 17 章 打造 Skill：将方法论蒸馏为可执行 Skill&quot;">​</a></h1><h2 id="_17-1-什么是-打造-skill" tabindex="-1">17.1 什么是&quot;打造 Skill&quot; <a class="header-anchor" href="#_17-1-什么是-打造-skill" aria-label="Permalink to &quot;17.1 什么是&quot;打造 Skill&quot;&quot;">​</a></h2><p>第 5 章我们学会了&quot;用&quot;Skill。这一章学&quot;造&quot;。</p><p>打造 Skill 的过程，本质上是一次<strong>方法论蒸馏</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的一次成功实践 → 提炼出可复用的步骤 → 写成 Skill → 下次一键调用</span></span></code></pre></div><h2 id="_17-2-什么时候值得造一个-skill" tabindex="-1">17.2 什么时候值得造一个 Skill <a class="header-anchor" href="#_17-2-什么时候值得造一个-skill" aria-label="Permalink to &quot;17.2 什么时候值得造一个 Skill&quot;">​</a></h2><ul><li>同一件事，你已经让我做过 <strong>2～3 次以上</strong>；</li><li>步骤基本固定，只是输入在变；</li><li>你和同事都频繁需要这个能力；</li><li>你想把个人经验变成团队资产。</li></ul><h2 id="_17-3-打造-skill-的五步法" tabindex="-1">17.3 打造 Skill 的五步法 <a class="header-anchor" href="#_17-3-打造-skill-的五步法" aria-label="Permalink to &quot;17.3 打造 Skill 的五步法&quot;">​</a></h2><p><strong>第 1 步：回顾成功案例</strong></p><p>找出最近一次做得好的任务，把全过程记下来：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务：合并 CSV</span></span>
<span class="line"><span>成功路径：读 README → 理解格式 → 写脚本 → 验证行数 → 输出</span></span></code></pre></div><p><strong>第 2 步：提炼可复用步骤</strong></p><p>去掉&quot;这一次的特殊性&quot;，留下&quot;下一次也适用&quot;的骨架：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入：多个 CSV 文件</span></span>
<span class="line"><span>步骤：读格式说明 → 检查字段 → 合并 → 校验行数 → 输出</span></span>
<span class="line"><span>输出：合并后的文件 + 校验报告</span></span></code></pre></div><p><strong>第 3 步：写清边界与约定</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>适用：同构 CSV 合并</span></span>
<span class="line"><span>不适用：异构/超大文件</span></span>
<span class="line"><span>约定：保留表头、数值取两位、必须校验</span></span></code></pre></div><p><strong>第 4 步：命名并测试</strong></p><ul><li>名字要能&quot;望文生义&quot;：<code>merge-csv</code>、<code>weekly-report</code>；</li><li>用真实数据测 2～3 次，确保稳定。</li></ul><p><strong>第 5 步：沉淀与共享</strong></p><ul><li>存入团队可访问的位置；</li><li>写一句话说明&quot;什么时候用它&quot;；</li><li>让团队其他人试用，收集反馈迭代。</li></ul><h2 id="_17-4-好-skill-的检查清单" tabindex="-1">17.4 好 Skill 的检查清单 <a class="header-anchor" href="#_17-4-好-skill-的检查清单" aria-label="Permalink to &quot;17.4 好 Skill 的检查清单&quot;">​</a></h2><ul><li>✅ 名称直观，说明清楚&quot;何时用/何时不用&quot;；</li><li>✅ 步骤可执行，不依赖特定上下文；</li><li>✅ 输入输出有约定，验收标准明确；</li><li>✅ 处理边界写清，超出边界会拒绝或提示；</li><li>✅ 有测试记录，不是&quot;我猜能用&quot;。</li></ul><h2 id="_17-5-常见误区" tabindex="-1">17.5 常见误区 <a class="header-anchor" href="#_17-5-常见误区" aria-label="Permalink to &quot;17.5 常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正确做法</th></tr></thead><tbody><tr><td>把一次性任务做成 Skill</td><td>先确认真的会重复</td></tr><tr><td>步骤太依赖具体文件</td><td>用占位符，输入参数化</td></tr><tr><td>只写&quot;做什么&quot;不写&quot;怎么验&quot;</td><td>每一步配验收</td></tr><tr><td>一次想做一个大而全的 Skill</td><td>小而精，先解决一个问题</td></tr></tbody></table><h2 id="_17-6-练习" tabindex="-1">17.6 练习 <a class="header-anchor" href="#_17-6-练习" aria-label="Permalink to &quot;17.6 练习&quot;">​</a></h2><ol><li>回顾你最近一个成功任务，按五步法写出 Skill 初稿；</li><li>用一套新的真实输入测试它，记录哪里需要修正；</li><li>迭代到&quot;换输入也能稳定跑&quot;为止，然后分享给同事试用。</li></ol><blockquote><p>小结：<strong>Skill 是经验的容器。</strong> 造 Skill 最大的收获不是技能本身，而是逼你把&quot;我好像会做&quot;变成&quot;我知道怎么做，而且能做对&quot;。</p></blockquote>`,27)])])}const k=a(e,[["render",o]]);export{h as __pageData,k as default};
